-- Authoritative club data. Critical mutations belong in SECURITY DEFINER command functions,
-- not direct browser CRUD. Apply this migration with Supabase CLI.
create extension if not exists pgcrypto;
create type participant_status as enum ('READY','PLAYING','RESTING','AWAY','OUT','LEFT');
create type session_status as enum ('LIVE','CLOSED','CANCELLED');
create type match_status as enum ('PREPARED','IN_PROGRESS','COMPLETED','ABANDONED');
create type set_status as enum ('IN_PROGRESS','COMPLETED','ABANDONED');
create type membership_type as enum ('MEMBER','GUEST');
create type club_role as enum ('CLUB_ADMIN','FINANCE_ADMIN');
create type payment_method as enum ('CASH','BANK','SHOPEEPAY');
create type expense_category as enum ('COURT','SHUTTLECOCK','OTHER');
create table clubs(id uuid primary key default gen_random_uuid(), name text not null, logo_path text, created_at timestamptz not null default now());
create table club_roles(club_id uuid references clubs on delete cascade, user_id uuid references auth.users on delete cascade, role club_role not null, primary key(club_id,user_id,role));
create table players(id uuid primary key default gen_random_uuid(),club_id uuid not null references clubs on delete cascade,display_name text not null check(length(trim(display_name))>0),avatar_path text,membership_type membership_type not null default 'MEMBER',is_active boolean not null default true,created_at timestamptz not null default now());
create table player_ratings(player_id uuid primary key references players on delete cascade,rating numeric not null default 1200,uncertainty numeric not null default 0.7 check(uncertainty>=0),updated_at timestamptz not null default now());
create table sessions(id uuid primary key default gen_random_uuid(),club_id uuid not null references clubs,status session_status not null default 'LIVE',fee_per_person integer check(fee_per_person is null or fee_per_person>0),started_at timestamptz not null default now(),closed_at timestamptz,created_by_user_id uuid references auth.users,created_at timestamptz not null default now());
create unique index one_live_session_per_club on sessions(club_id) where status='LIVE';
create table session_participants(id uuid primary key default gen_random_uuid(),session_id uuid not null references sessions on delete cascade,player_id uuid not null references players,status participant_status not null,checked_in_at timestamptz not null default now(),left_at timestamptz,ready_since timestamptz,leave_after_match boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(session_id,player_id));
create table participant_status_periods(id uuid primary key default gen_random_uuid(),session_participant_id uuid not null references session_participants on delete cascade,status participant_status not null,started_at timestamptz not null default now(),ended_at timestamptz,check(ended_at is null or ended_at>=started_at));
create unique index one_open_period_per_participant on participant_status_periods(session_participant_id) where ended_at is null;
create table matches(id uuid primary key default gen_random_uuid(),session_id uuid not null references sessions on delete cascade,sequence_number integer not null,status match_status not null default 'PREPARED',rotation_recommendation_id uuid,started_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now(),unique(session_id,sequence_number));
create unique index one_active_match_per_session on matches(session_id) where status='IN_PROGRESS';
create table sets(id uuid primary key default gen_random_uuid(),match_id uuid not null references matches on delete cascade,set_number smallint not null check(set_number in (1,2)),status set_status not null default 'IN_PROGRESS',team_a_score smallint check(team_a_score>=0),team_b_score smallint check(team_b_score>=0),started_at timestamptz,completed_at timestamptz,unique(match_id,set_number),check((status='COMPLETED') = (team_a_score is not null and team_b_score is not null)));
create table set_players(set_id uuid references sets on delete cascade,player_id uuid references players,team text not null check(team in ('A','B')),primary key(set_id,player_id));
create table rotation_recommendations(id uuid primary key default gen_random_uuid(),session_id uuid not null references sessions on delete cascade,algorithm_version text not null,diagnostics jsonb,created_at timestamptz not null default now());
create table rotation_candidate_scores(recommendation_id uuid references rotation_recommendations on delete cascade,player_id uuid references players,rank integer not null,priority_score numeric,recommended boolean not null,diagnostics jsonb,primary key(recommendation_id,player_id));
create table pairing_recommendations(id uuid primary key default gen_random_uuid(),match_id uuid not null references matches on delete cascade,algorithm_version text not null,diagnostics jsonb,created_at timestamptz not null default now());
create table pairing_recommendation_players(recommendation_id uuid references pairing_recommendations on delete cascade,player_id uuid references players,recommended_team text not null check(recommended_team in ('A','B')),rating_snapshot numeric not null,uncertainty_snapshot numeric not null,primary key(recommendation_id,player_id));
create table player_rating_history(id uuid primary key default gen_random_uuid(),player_id uuid not null references players,set_id uuid references sets,source text not null check(source in ('SET_RESULT','MANUAL_ADJUSTMENT','INITIALIZATION')),rating_before numeric not null,rating_after numeric not null,uncertainty_before numeric not null,uncertainty_after numeric not null,algorithm_version text,created_at timestamptz not null default now());
create table session_obligations(id uuid primary key default gen_random_uuid(),session_id uuid not null references sessions,player_id uuid not null references players,amount integer not null check(amount>0),created_at timestamptz not null default now(),unique(session_id,player_id));
create table payments(id uuid primary key default gen_random_uuid(),club_id uuid not null references clubs,player_id uuid not null references players,amount integer not null check(amount>0),method payment_method not null,received_at timestamptz not null default now(),recorded_by_user_id uuid references auth.users,created_at timestamptz not null default now());
create table payment_allocations(id uuid primary key default gen_random_uuid(),payment_id uuid not null references payments on delete cascade,obligation_id uuid not null references session_obligations on delete cascade,amount integer not null check(amount>0),created_at timestamptz not null default now());
create table expenses(id uuid primary key default gen_random_uuid(),club_id uuid not null references clubs,session_id uuid references sessions,category expense_category not null,description text,amount integer not null check(amount>0),occurred_at timestamptz not null default now(),recorded_by_user_id uuid references auth.users,created_at timestamptz not null default now());
create table finance_submissions(id uuid primary key default gen_random_uuid(),session_id uuid not null references sessions,reported_court_cost integer check(reported_court_cost>0),reported_shuttlecock_cost integer check(reported_shuttlecock_cost>0),notes text,submitted_by_operator_lease_id uuid,submitted_at timestamptz not null default now(),status text not null default 'PENDING' check(status in ('PENDING','CONFIRMED','REJECTED')),reviewed_by_user_id uuid references auth.users,reviewed_at timestamptz);
create table session_operator_credentials(id uuid primary key default gen_random_uuid(),session_id uuid not null unique references sessions on delete cascade,pin_hash text not null,created_at timestamptz not null default now());
create table session_operator_leases(id uuid primary key default gen_random_uuid(),session_id uuid not null references sessions on delete cascade,device_id text not null,revoked_at timestamptz,created_at timestamptz not null default now());
create unique index one_active_lease_per_session on session_operator_leases(session_id) where revoked_at is null;
create table session_events(id uuid primary key default gen_random_uuid(),session_id uuid not null references sessions on delete cascade,event_type text not null,entity_type text,entity_id uuid,actor_user_id uuid references auth.users,actor_operator_lease_id uuid references session_operator_leases,metadata jsonb,created_at timestamptz not null default now());
alter table clubs enable row level security; alter table players enable row level security; alter table sessions enable row level security;
-- Public-safe views/policies and SECURITY DEFINER command functions are intentionally added before production deployment.
